```Gateways/Setak.IMS.Blazor.UI/Pages/EquipmentOutField/Editor.razor
@using Setak.IMS.Classes.DTOs.Equ
@using Setak.IMS.Classes.DTOs.Pub
@using Setak.IMS.Classes.Domains.Enums

<PageLoading LoadContent="(isInitialized && model != null)" @ref="loadingRef">
    <Form>
        <Validations MissingFieldsErrorMessage="خطای اعتبارسنجی" Mode="ValidationMode.Auto" ValidateOnLoad="false" Model="model" @ref="validationsRef">

            @* Row 1 *@
            <Row>
                <Column ColumnSize="ColumnSize.Is6.OnDesktop.Is6.OnTablet.IsFull.OnMobile">
                    <Validation>
                        <Field>
                            @{
                                var id = ReflectionHelper.GetPropertyName<EquipmentOutFieldDto>(x => x.Name);
                                var label = AttributesHelper.GetDisplayNameValue<EquipmentOutFieldDto>(x => x.Name) ?? id;
                            }
<|editable_region_start|>
                            <FieldLabel>@label</FieldLabel>
                            <TextEdit ElementId="@id" @bind-Text="model.Name">
                                <Feedback>
                                    <ValidationError/>
                                </Feedback>
                            </TextEdit>
                        </Field>
                    </Validation>
                </Column>

            </Row>
<|user_cursor_is_here|>

                <Column ColumnSize="ColumnSize.Is6.OnDesktop.Is6.OnTablet.IsFull.OnMobile">
                    <Field>
                        @{
                            var id = ReflectionHelper.GetPropertyName<EquipmentOutFieldDto>(x => x.WeekendDays);
                            var label = AttributesHelper.GetDisplayNameValue<EquipmentOutFieldDto>(x => x.WeekendDays) ?? id;
                        }
                        <FieldLabel>@label</FieldLabel>
                        <div class="d-flex flex-wrap gap-3 mt-2">
                            @foreach (WeekendDay wd in Enum.GetValues<WeekendDay>())
<|editable_region_end|>

                            {
                                @if (wd != WeekendDay.None)
                                {
                                    <Check TValue="bool" @bind-Checked="@_weekendFlags[wd]"
                                           CheckedStateChanged="@(() => ToggleWeekend(wd))"/>
                                    <span class="me-2">@GetWeekendDayName(wd)</span>
                                }
                            }
                        </div>
                    </Field>
                </Column>
            </Row>

            @* Row 3 *@
            <Row>
                <Column ColumnSize="ColumnSize.IsFull">
                    <Validation>
                        <Field>
                            @{
                                var id = ReflectionHelper.GetPropertyName<EquipmentOutFieldDto>(x => x.Description);
                                var label = AttributesHelper.GetDisplayNameValue<EquipmentOutFieldDto>(x => x.Description) ?? id;
                            }
                            <FieldLabel>@label</FieldLabel>
                            <MemoEdit ElementId="@id" @bind-Text="model.Description" Rows="3">
```

